import Foundation

// DRAFT CONTENT — not yet clinically reviewed. See the header of TreatmentOptions.swift.
// Vascular, heart and chest, and injury (trauma) conditions. Percentages are approximate ranges
// from the cited sources and must be verified by a vascular surgeon, cardiologist, cardiac or
// thoracic surgeon, radiation oncologist and trauma surgeon before release.

extension TreatmentGuides {
    static let vascular: [ConditionGuide] = [carotidStenosis, abdominalAorticAneurysm, claudication]
    static let cardiothoracic: [ConditionGuide] = [stableCoronaryDisease, aorticStenosis, earlyLungCancer]
    static let trauma: [ConditionGuide] = [splenicInjury, ribFractures, liverInjury]

    // MARK: - Asymptomatic carotid stenosis

    static let carotidStenosis = ConditionGuide(
        id: "asymptomatic-carotid-stenosis",
        name: "Carotid artery narrowing without symptoms",
        alsoCalled: "Asymptomatic carotid stenosis, carotid artery disease, carotid plaque",
        symbol: "brain.head.profile",
        summary: "Fatty plaque narrows one of the two main arteries in the neck that carry blood to the brain. 'Asymptomatic' means it was found on a scan or by a doctor listening to your neck, and you have not had a stroke or mini-stroke (TIA) from that side. The goal of every option is to prevent a future stroke.",
        naturalHistory: [
            "With modern medicines (a statin, aspirin or a similar drug, and good blood pressure control), the yearly chance of a stroke from an asymptomatic narrowing is low — roughly 0.5 to 1 in 100 per year in recent studies.",
            "Older trials from the 1990s and 2000s found higher stroke rates without surgery, but medicines and smoking rates have changed a lot since then.",
            "The narrowing can stay the same for years. If you develop stroke or TIA symptoms, the situation changes: the risk of another stroke in the next weeks is much higher and a procedure is usually advised quickly.",
        ],
        whenSurgeryIsOffered: [
            "A narrowing of about 70% or more, usually measured with ultrasound, CT or MRI scans.",
            "You are expected to live at least another 5 years, so the long-term benefit can outweigh the upfront risk of the procedure.",
            "The hospital and surgeon have a low stroke-and-death rate for the procedure (guidelines suggest under 3 in 100 for people without symptoms).",
        ],
        urgentSigns: [
            "Sudden face drooping, arm or leg weakness, trouble speaking, loss of vision in one eye, or sudden loss of balance — call 911 right away. These are signs of a stroke or TIA, even if they go away.",
            "If you have had stroke or TIA symptoms, tell your doctor: you are no longer 'asymptomatic', and an operation or stent within about 2 weeks is often advised.",
        ],
        improvementDefinition: "Because the goal is prevention, 'meaningful improvement' here means being free of stroke and of death caused by the procedure, about 4–5 years after starting treatment. The risk of the procedure itself is counted in.",
        options: [
            TreatmentOption(
                id: "carotid-medical", name: "Best medical therapy", tier: .conservative,
                summary: "Lowering your stroke risk with medicines and lifestyle changes instead of a procedure. This is advised for everyone with carotid narrowing, whether or not they also have a procedure.",
                whatHappens: ["A high-dose statin to lower cholesterol and steady the plaque.", "Aspirin or clopidogrel to make blood less sticky.", "Blood pressure and diabetes control, quitting smoking and regular exercise.", "A carotid ultrasound every 1–2 years to watch for changes."],
                anesthesia: "None", hospitalStay: "None", recovery: "Ongoing; regular checkups.",
                bestFor: ["Most people with asymptomatic narrowing", "People with other serious health problems or a shorter life expectancy", "People who prefer to avoid procedure risks"],
                lessSuitableIf: ["You have had stroke or TIA symptoms from that side", "You cannot take statins or antiplatelet medicines"],
                outcomes: OptionOutcomes(improvement: PercentRange(90, 97), seriousComplications: PercentRange(1, 3), furtherTreatment: PercentRange(5, 15)),
                keyFindings: [
                    "In the CREST-2 trial, people treated with intensive medicines alone had a stroke rate of roughly 5–6 in 100 over 4 years. Endarterectomy did not clearly lower this, while stenting did (about 3 in 100). These figures are approximate and need confirming against the final paper (Brott 2025).",
                    "Stroke rates on medicines alone have fallen over time, which is why older trials may overstate the benefit of surgery (Abbott 2009 review).",
                ],
                sideEffects: [
                    SE.make("Stroke while on medicines alone", "About 3–6 in 100 over 4–5 years in recent trials; older trials found higher rates.", 3, 6, .serious),
                    SE.make("Muscle aches (statin)", "Usually mild; switching statin or dose often helps.", 5, 10, .mild),
                    SE.make("Easy bruising (aspirin or clopidogrel)", "Small bruises and nosebleeds that last longer.", 10, 20, .mild),
                    SE.make("Serious bleeding (aspirin or clopidogrel)", "Bleeding from the stomach or, rarely, the brain over several years of use.", 0.5, 2, .serious),
                    SE.make("Dizziness (blood pressure medicines)", "Mainly when standing up quickly or when starting a new dose.", 5, 10, .mild),
                ],
                evidence: .moderate,
                availability: "Always available, usually through your primary care doctor, cardiologist or neurologist. Medicines are covered by Medicare Part D and most insurers. A surgeon may focus on the procedure because medicines are usually managed by other doctors.",
                sources: ["Brott TG et al. N Engl J Med 2025 (CREST-2)", "Abbott AL. Stroke 2009;40:e573–83", "Naylor R et al. Eur J Vasc Endovasc Surg 2023;65:7–111"]),

            TreatmentOption(
                id: "carotid-transfemoral-stent", name: "Carotid stenting through the groin", tier: .interventional,
                summary: "A thin tube is passed from an artery in the groin up to the neck, and a small mesh tube (stent) is opened inside the narrowing to hold it open.",
                whatHappens: ["Done awake with numbing medicine at the groin.", "A filter or similar device catches loose debris while the stent is placed.", "Two antiplatelet medicines for at least a month afterward, plus best medical therapy."],
                anesthesia: "Local anesthetic with light sedation", hospitalStay: "Usually 1 night", recovery: "Most people are back to normal activities within a few days.",
                bestFor: ["People with a 'hostile neck' (past neck surgery or radiation) or a narrowing high in the neck", "People at higher risk from open surgery because of heart or lung disease"],
                lessSuitableIf: ["Age over about 70–75, when stroke risk from the procedure is higher", "Very twisted or heavily calcified arteries in the chest", "Unable to take two antiplatelet medicines"],
                outcomes: OptionOutcomes(improvement: PercentRange(92, 97), seriousComplications: PercentRange(2, 5), furtherTreatment: PercentRange(2, 7)),
                keyFindings: [
                    "In the CREST trial (2,502 people, about half without symptoms), stenting and endarterectomy had similar overall results; stenting had more early strokes (about 4 vs 2 in 100) and fewer heart attacks (about 1 vs 2 in 100) (Brott 2010).",
                    "In ACST-2 (3,625 people without symptoms), stenting and endarterectomy had similar rates of disabling stroke or death, about 1 in 100 each around the time of the procedure (Halliday 2021).",
                ],
                sideEffects: [
                    SE.make("Stroke during or soon after the procedure", "From debris breaking off the plaque. Most are minor, but some are disabling.", 2, 4, .serious),
                    SE.make("Heart attack", "Less common than with open surgery.", 0.5, 1.5, .serious),
                    SE.make("Slow heart rate or low blood pressure", "From pressure on the artery's sensor. Usually temporary and treated with fluids or medicine.", 5, 20, .moderate),
                    SE.make("Bleeding or bruising at the groin", "A lump or bruise where the tube went in; rarely needs repair.", 1, 5, .moderate),
                    SE.make("Artery narrows again", "Inside the stent over the following years; only some need a repeat procedure.", 3, 7, .moderate),
                    SE.death(0.2, 1),
                ],
                evidence: .strong,
                availability: "Offered by vascular surgeons, interventional cardiologists, radiologists and neurointerventionalists. Since 2023 Medicare covers stenting for people without symptoms with at least 70% narrowing after a shared decision-making visit.",
                sources: ["Brott TG et al. N Engl J Med 2010;363:11–23", "Brott TG et al. N Engl J Med 2016;374:1021–31", "Halliday A et al. Lancet 2021;398:1065–73"]),

            TreatmentOption(
                id: "carotid-tcar", name: "Transcarotid artery revascularization (TCAR)", tier: .minimallyInvasive,
                summary: "A stent placed through a small cut at the base of the neck. Blood flow in the artery is briefly reversed so that loose debris is pulled away from the brain and filtered.",
                whatHappens: ["A cut of about 2–3 cm above the collarbone.", "A tube in the carotid artery is connected to a tube in a groin vein, so blood flows backward through a filter while the stent is placed.", "Two antiplatelet medicines afterward."],
                anesthesia: "General anesthesia or local anesthetic with sedation", hospitalStay: "Usually 1 night", recovery: "Back to most activities within a few days; avoid heavy lifting for about a week.",
                bestFor: ["People at higher risk from endarterectomy", "Older adults who would be at higher stroke risk with stenting through the groin"],
                lessSuitableIf: ["The narrowing is too close to the collarbone or the artery is too short to reach", "Unable to take two antiplatelet medicines"],
                outcomes: OptionOutcomes(improvement: PercentRange(93, 97), seriousComplications: PercentRange(2, 4), furtherTreatment: PercentRange(2, 6)),
                keyFindings: [
                    "In the ROADSTER study of 141 higher-risk people, the stroke rate within 30 days was about 1.4 in 100 (Kwolek 2015).",
                    "In a large US registry, TCAR had fewer in-hospital strokes or deaths than stenting through the groin (about 1.6 vs 3.1 in 100). This was not a randomized trial (Malas 2019).",
                ],
                sideEffects: [
                    SE.make("Stroke during or soon after the procedure", "Lower than stenting through the groin in registries.", 1, 2, .serious),
                    SE.make("Heart attack", "Usually in people with existing heart disease.", 0.5, 1.5, .serious),
                    SE.make("Bleeding or swelling in the neck", "Occasionally needs a return to the operating room.", 1, 4, .moderate),
                    SE.make("Nerve injury affecting voice or swallowing", "Usually temporary.", 0.5, 2, .moderate),
                    SE.make("Artery narrows again", "Inside the stent over the following years.", 2, 6, .moderate),
                    SE.death(0.3, 1),
                ],
                evidence: .limited,
                availability: "Offered mainly by vascular surgeons at a growing number of US hospitals. Covered by Medicare under its carotid stenting policy. TCAR has not yet been compared with endarterectomy or medicines alone in a randomized trial, and long-term results are still being collected. A surgeon who doesn't do TCAR may not mention it; a surgeon who does may not mention medicines alone.",
                sources: ["Kwolek CJ et al. J Vasc Surg 2015;62:1227–34", "Malas MB et al. JAMA 2019;322:2313–22"]),

            TreatmentOption(
                id: "carotid-endarterectomy", name: "Carotid endarterectomy", tier: .traditional,
                summary: "The standard operation. Through a cut on the side of the neck, the artery is opened and the plaque is peeled out, then the artery is closed, often with a patch.",
                whatHappens: ["A cut of about 8–10 cm along the front of the neck muscle.", "The artery is clamped briefly; some surgeons use a temporary bypass tube.", "Best medical therapy continues afterward."],
                anesthesia: "General anesthesia, or local anesthetic so you stay awake (both have similar results)", hospitalStay: "1–2 nights", recovery: "Most people are back to normal within 1–2 weeks; no driving for about a week.",
                bestFor: ["A narrowing of 70% or more in someone expected to live at least 5 more years", "A surgeon and hospital with a low complication rate"],
                lessSuitableIf: ["Past neck surgery or radiation, or a narrowing very high in the neck", "Serious heart or lung disease"],
                outcomes: OptionOutcomes(improvement: PercentRange(92, 97), seriousComplications: PercentRange(2, 5), furtherTreatment: PercentRange(2, 5)),
                keyFindings: [
                    "In ACST-1 (3,120 people without symptoms), stroke over 10 years was about 13 in 100 after surgery vs 18 in 100 with delayed or no surgery. Medicines were less effective then than now (Halliday 2010).",
                    "In CREST-2, endarterectomy plus intensive medicines did not clearly lower stroke over 4 years compared with intensive medicines alone (roughly 4 vs 5 in 100). These figures are approximate (Brott 2025).",
                ],
                sideEffects: [
                    SE.make("Stroke during or soon after surgery", "Most often within the first day.", 1, 3, .serious),
                    SE.make("Heart attack", "More common than after stenting.", 1, 2.5, .serious),
                    SE.make("Nerve injury affecting voice, swallowing or the tongue", "Usually recovers within weeks to months; lasting problems are uncommon.", 2, 5, .moderate),
                    SE.make("Bleeding or swelling in the neck", "Occasionally needs a return to the operating room.", 1, 5, .moderate),
                    SE.make("Numbness of the skin near the cut or the earlobe", "Common and often lasting, but usually not bothersome.", 20, 50, .mild),
                    SE.woundInfection(0.1, 1),
                    SE.death(0.2, 1),
                ],
                evidence: .strong,
                availability: "Widely available from vascular surgeons and some neurosurgeons. Covered by Medicare and most insurers.",
                sources: ["Halliday A et al. Lancet 2004;363:1491–502", "Halliday A et al. Lancet 2010;376:1074–84", "Executive Committee for the ACAS. JAMA 1995;273:1421–8", "Brott TG et al. N Engl J Med 2025 (CREST-2)"]),
        ],
        comparisons: [
            ComparisonStudy(name: "ACST-1", compared: "Immediate endarterectomy vs deferred surgery with medicines (3,120 people without symptoms)",
                finding: "Surgery roughly halved stroke over 5 years and lowered it over 10 years (about 13 vs 18 in 100), but medicines then were less intensive than today.", citation: "Halliday 2004, 2010, Lancet"),
            ComparisonStudy(name: "CREST", compared: "Stenting through the groin vs endarterectomy (2,502 people with or without symptoms)",
                finding: "Similar overall results. Stenting had more early strokes, surgery more heart attacks. Results over 10 years were similar.", citation: "Brott 2010, 2016, N Engl J Med"),
            ComparisonStudy(name: "ACST-2", compared: "Stenting vs endarterectomy in people without symptoms (3,625 people)",
                finding: "About 1 in 100 had a disabling stroke or died around the procedure with either; long-term stroke rates were similar.", citation: "Halliday 2021, Lancet"),
            ComparisonStudy(name: "CREST-2", compared: "Intensive medicines alone vs intensive medicines plus stenting, and vs medicines plus endarterectomy",
                finding: "Stenting plus medicines lowered stroke over about 4 years compared with medicines alone; endarterectomy did not clearly do so. Final numbers should be checked against the published paper.", citation: "Brott 2025, N Engl J Med"),
        ],
        questionsToAsk: [
            "What is my stroke risk each year on medicines alone, and how much would a procedure lower it?",
            "What are your own stroke and death rates for this procedure in people without symptoms?",
            "Am I on the best medicines now — a high-dose statin, an antiplatelet and good blood pressure control?",
            "Would stenting, TCAR or endarterectomy suit my artery and my health best, and why?",
            "What does the CREST-2 trial mean for someone like me?",
        ],
        specialty: .vascular)

    // MARK: - Abdominal aortic aneurysm

    static let abdominalAorticAneurysm = ConditionGuide(
        id: "abdominal-aortic-aneurysm",
        name: "Abdominal aortic aneurysm (AAA)",
        alsoCalled: "AAA, aortic aneurysm, swollen or ballooning aorta",
        symbol: "circle.circle",
        summary: "A weak area of the main artery in the belly (the aorta) swells like a balloon. Most cause no symptoms. The danger is that a large aneurysm can burst (rupture), which is often fatal. The goal of treatment is to prevent rupture.",
        naturalHistory: [
            "Small aneurysms (under about 5.5 cm in men or 5.0 cm in women) usually grow slowly, a few millimeters a year. Their chance of bursting is about 1 in 100 per year or less.",
            "The chance of rupture rises steeply with size. For aneurysms 5.5–6 cm it is roughly 5–10 in 100 per year, and higher for larger ones.",
            "In two large trials, repairing small aneurysms early did not help people live longer than careful ultrasound monitoring. About 6 in 10 of the monitored people eventually needed repair as their aneurysm grew.",
            "When an aneurysm bursts, about 8 in 10 people die, including many who don't reach a hospital in time.",
        ],
        whenSurgeryIsOffered: [
            "An aneurysm 5.5 cm or larger in men, or about 5.0 cm or larger in women.",
            "Fast growth — more than about 1 cm in a year.",
            "Belly or back pain caused by the aneurysm, or a rupture (emergency surgery).",
        ],
        urgentSigns: [
            "Sudden severe pain in the belly, back or side, especially with dizziness, fainting, sweating or a fast heartbeat — call 911. This may be a rupture and needs emergency surgery.",
            "New tenderness over a known aneurysm — get checked the same day.",
            "For a burst, large or painful aneurysm, repair is clearly the safest choice. Monitoring is only for small aneurysms without symptoms.",
        ],
        improvementDefinition: "Because the goal is prevention, 'meaningful improvement' here means being free of aneurysm rupture and of death from the aneurysm or its repair, about 5 years after diagnosis or treatment.",
        options: [
            TreatmentOption(
                id: "aaa-surveillance", name: "Ultrasound monitoring and medicines (for small aneurysms)", tier: .conservative,
                summary: "Regular scans to measure the aneurysm, with steps to lower heart and stroke risk and slow growth. Repair is offered if it reaches the size threshold or grows fast.",
                whatHappens: ["An ultrasound every 6 months to 3 years, depending on size.", "Quit smoking — the most important step to slow growth.", "Blood pressure control, a statin and usually aspirin."],
                anesthesia: "None", hospitalStay: "None", recovery: "Ongoing monitoring.",
                bestFor: ["Aneurysms under 5.5 cm in men or 5.0 cm in women without symptoms"],
                lessSuitableIf: ["A large, fast-growing or painful aneurysm", "Not able to keep up with regular scans"],
                outcomes: OptionOutcomes(improvement: PercentRange(95, 99), seriousComplications: PercentRange(1, 5), furtherTreatment: PercentRange(60, 75)),
                keyFindings: [
                    "In the UK Small Aneurysm Trial (1,090 people with 4.0–5.5 cm aneurysms), early open repair did not improve survival compared with ultrasound monitoring (UK Small Aneurysm Trial 1998).",
                    "The US ADAM trial found the same, and about 6 in 10 monitored people had repair over the following years (Lederle 2002).",
                    "Early repair with EVAR also did not improve survival for small aneurysms (Filardo 2020 Cochrane review).",
                ],
                sideEffects: [
                    SE.make("Aneurysm bursts while being monitored", "About 1 in 100 per year for small aneurysms; higher in women and smokers.", 1, 5, .serious),
                    SE.make("Aneurysm grows to the size where repair is advised", "Expected for most people over several years.", 60, 75, .moderate),
                    SE.make("Worry about living with an aneurysm", "Common; talking it through with your team helps.", 10, 30, .mild),
                    SE.make("Muscle aches (statin) or dizziness (blood pressure medicines)", "Usually mild and manageable by adjusting medicines.", 5, 10, .mild),
                ],
                evidence: .strong,
                availability: "Always available. Medicare pays for a one-time screening ultrasound for some men who have smoked and people with a family history. Monitoring scans are covered.",
                sources: ["UK Small Aneurysm Trial Participants. Lancet 1998;352:1649–55", "Lederle FA et al. N Engl J Med 2002;346:1437–44", "Filardo G et al. Cochrane 2020;CD001835", "Chaikof EL et al. J Vasc Surg 2018;67:2–77"]),

            TreatmentOption(
                id: "aaa-no-repair", name: "Not repairing a large aneurysm (for people at very high surgical risk)", tier: .conservative,
                summary: "For people with serious illnesses or frailty, choosing medicines and comfort-focused care instead of repair. This accepts a real risk of rupture in exchange for avoiding the risks of surgery.",
                whatHappens: ["Medicines for blood pressure and cholesterol.", "Planning ahead with your family about what you would want if the aneurysm burst.", "Sometimes palliative care support."],
                anesthesia: "None", hospitalStay: "None", recovery: "Not applicable.",
                bestFor: ["People with a short life expectancy from other illnesses", "People who would not want, or could not survive, repair"],
                lessSuitableIf: ["People healthy enough for EVAR or open repair who want to lower their rupture risk"],
                outcomes: OptionOutcomes(improvement: nil, seriousComplications: nil, furtherTreatment: nil),
                keyFindings: [
                    "In EVAR-2, people unfit for open surgery who had EVAR had fewer aneurysm-related deaths but did not live longer overall than those not repaired, because many died of other illnesses (EVAR Trial Investigators 2010).",
                    "In US veterans unable to have surgery, aneurysms 5.5–5.9 cm burst at about 9 in 100 per year, and larger ones more often (Lederle 2002).",
                ],
                sideEffects: [
                    SE.make("Aneurysm bursts", "About 5–15 in 100 per year for aneurysms 5.5 cm and larger, rising with size. Usually fatal.", 5, 15, .serious),
                    SE.make("Worry for you and your family", "Advance planning and palliative care can help.", 20, 50, .mild),
                    SE.make("Medicine side effects", "Dizziness, muscle aches or tiredness from blood pressure and cholesterol medicines.", 5, 10, .mild),
                ],
                evidence: .moderate,
                availability: "Always an option. Your surgeon should discuss it if your risk from repair is high.",
                sources: ["EVAR Trial Investigators. N Engl J Med 2010;362:1872–80", "Lederle FA et al. JAMA 2002;287:2968–72"]),

            TreatmentOption(
                id: "aaa-evar", name: "Endovascular aneurysm repair (EVAR)", tier: .minimallyInvasive,
                summary: "A fabric-covered stent graft is passed up through the arteries in the groin and opened inside the aneurysm, so blood flows through the graft and no longer presses on the weak wall.",
                whatHappens: ["Small cuts or needle punctures in both groins.", "The graft is guided into place using X-ray images and contrast dye.", "Lifelong scans (CT or ultrasound) to check the graft."],
                anesthesia: "General, regional (spinal) or local anesthetic with sedation", hospitalStay: "1–2 nights", recovery: "Most people are back to normal activities within 1–2 weeks.",
                bestFor: ["Aneurysms that have reached the repair threshold, with a shape that suits a stent graft", "People at higher risk from open surgery"],
                lessSuitableIf: ["A short or angled 'neck' of normal aorta above the aneurysm", "Narrow or very diseased groin and pelvic arteries", "Unable to have lifelong follow-up scans, or kidney disease that makes contrast dye risky"],
                outcomes: OptionOutcomes(improvement: PercentRange(92, 97), seriousComplications: PercentRange(3, 10), furtherTreatment: PercentRange(15, 30)),
                keyFindings: [
                    "In EVAR-1, death within 30 days was about 1.7 in 100 after EVAR vs 4.7 in 100 after open repair (Greenhalgh 2004).",
                    "That early survival advantage faded within a few years. After about 8 years, more aneurysm-related deaths occurred in the EVAR group, mainly from late graft problems and rupture (Patel 2016).",
                    "In the US OVER trial, early death was lower with EVAR (0.5 vs 3.0 in 100), and long-term survival was similar (Lederle 2009, 2012).",
                ],
                sideEffects: [
                    SE.make("Leak around the graft (endoleak)", "Blood still reaches the aneurysm. Many need only monitoring; some need another procedure.", 15, 25, .moderate),
                    SE.make("Another procedure on the graft", "Over 10 or more years, usually through the groin.", 15, 30, .moderate),
                    SE.make("Graft leg blocks off", "Can cause leg pain on walking or a cold leg; usually fixed with another procedure.", 2, 5, .serious),
                    SE.make("Late aneurysm rupture despite the graft", "Rare, but the reason lifelong scans matter.", 1, 3, .serious),
                    SE.make("Groin wound or artery problems", "Bleeding, swelling or infection at the groin.", 2, 5, .moderate),
                    SE.make("Kidney injury from contrast dye", "Usually temporary; higher with existing kidney disease.", 1, 5, .moderate),
                    SE.death(0.5, 2),
                ],
                evidence: .strong,
                availability: "Widely available from vascular surgeons and some interventional radiologists. Covered by Medicare and most insurers. Grafts for more complex aneurysms (fenestrated or branched) are offered at fewer centers.",
                sources: ["Greenhalgh RM et al. Lancet 2004;364:843–8", "Patel R et al. Lancet 2016;388:2366–74", "Lederle FA et al. JAMA 2009;302:1535–42", "Lederle FA et al. N Engl J Med 2012;367:1988–97"]),

            TreatmentOption(
                id: "aaa-open-repair", name: "Open aneurysm repair", tier: .traditional,
                summary: "Through a cut in the belly or side, the aorta is clamped, the aneurysm is opened and a fabric tube graft is sewn in to replace the weak section.",
                whatHappens: ["A cut down the middle of the belly or across the side.", "The aorta is clamped while the graft is sewn in.", "Often a night or two in intensive care."],
                anesthesia: "General anesthesia, often with an epidural for pain relief", hospitalStay: "5–10 days", recovery: "About 2–3 months to feel back to normal.",
                bestFor: ["Younger, fitter people who want a durable repair with less need for lifelong scans", "Aneurysms whose shape doesn't suit a stent graft"],
                lessSuitableIf: ["Serious heart, lung or kidney disease", "Frailty or several past belly operations"],
                outcomes: OptionOutcomes(improvement: PercentRange(92, 97), seriousComplications: PercentRange(10, 25), furtherTreatment: PercentRange(5, 15)),
                keyFindings: [
                    "In the DREAM trial, early death and serious complications were higher after open repair than EVAR, but survival was similar after 2 years and beyond (Prinssen 2004; De Bruin 2010).",
                    "Over the long term, open repair needed fewer repeat procedures on the aorta than EVAR, though more people had hernia repairs (Patel 2016; Lederle 2012).",
                ],
                sideEffects: [
                    SE.anesthesia,
                    SE.make("Heart attack", "The aorta clamp puts strain on the heart.", 2, 5, .serious),
                    SE.make("Lung problems such as pneumonia", "Breathing exercises and early walking lower the risk.", 5, 10, .moderate),
                    SE.make("Kidney injury", "Usually temporary; rarely needs dialysis.", 3, 10, .moderate),
                    SE.make("Bowel damage from reduced blood flow", "Rare but serious; may need more surgery.", 1, 3, .serious),
                    SE.make("Hernia at the cut", "A bulge at the scar that may need repair later.", 5, 15, .moderate),
                    SE.make("Sexual problems in men", "Erection or ejaculation changes from nerves near the aorta.", 5, 25, .moderate),
                    SE.death(1, 5),
                ],
                evidence: .strong,
                availability: "Offered by vascular surgeons. Fewer surgeons now do many open repairs, so ask how many your team does each year. Covered by Medicare and most insurers.",
                sources: ["Prinssen M et al. N Engl J Med 2004;351:1607–18", "De Bruin JL et al. N Engl J Med 2010;362:1881–9", "Patel R et al. Lancet 2016;388:2366–74", "Lederle FA et al. N Engl J Med 2012;367:1988–97"]),
        ],
        comparisons: [
            ComparisonStudy(name: "UK Small Aneurysm Trial", compared: "Early open repair vs ultrasound monitoring for 4.0–5.5 cm aneurysms (1,090 people)",
                finding: "No survival benefit from early repair. Monitoring was safe for small aneurysms; the US ADAM trial agreed.", citation: "UK Small Aneurysm Trial 1998, Lancet; Lederle 2002, N Engl J Med"),
            ComparisonStudy(name: "EVAR-1", compared: "EVAR vs open repair (1,252 people)",
                finding: "Fewer early deaths with EVAR (about 1.7 vs 4.7 in 100), but more late graft problems and repeat procedures; after about 8 years, survival slightly favored open repair.", citation: "Greenhalgh 2004; Patel 2016, Lancet"),
            ComparisonStudy(name: "OVER trial", compared: "EVAR vs open repair in US veterans (881 people)",
                finding: "Lower early death with EVAR (0.5 vs 3.0 in 100); long-term survival was similar.", citation: "Lederle 2009, JAMA; Lederle 2012, N Engl J Med"),
            ComparisonStudy(name: "DREAM", compared: "EVAR vs open repair (351 people)",
                finding: "Fewer early complications with EVAR; survival was similar after 2 years, with more repeat procedures after EVAR.", citation: "Prinssen 2004; De Bruin 2010, N Engl J Med"),
        ],
        questionsToAsk: [
            "How big is my aneurysm, how fast is it growing, and what is my yearly risk of rupture at this size?",
            "Is my aneurysm the right shape for EVAR? What would follow-up scans involve?",
            "What are your hospital's death and complication rates for EVAR and for open repair?",
            "If I wait, how often will I be scanned, and at what size would you advise repair?",
        ],
        specialty: .vascular)

    // MARK: - Peripheral artery disease with claudication

    static let claudication = ConditionGuide(
        id: "pad-claudication",
        name: "Peripheral artery disease with leg pain on walking",
        alsoCalled: "Intermittent claudication, PAD, PVD, blocked leg arteries",
        symbol: "figure.walk",
        summary: "Narrowed or blocked arteries in the legs limit blood flow, causing cramping pain in the calf, thigh or buttock when you walk that goes away with a few minutes' rest. It is also a warning sign of heart attack and stroke risk.",
        naturalHistory: [
            "For most people, walking pain stays about the same or improves over 5 years; it gets worse in about 1 in 4.",
